                            { !!index && ' · ' }
                            <DeviceMetadata id={id} value={value} />
                        </Fragment>
                        : null,
                ) }
            </div>
        </div>
        <div className="mx_DeviceTile_actions">
            { children }
        </div>
    </div>;
};

